<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { activeWorkshops, listCustomers } from '../services/customers'
import { checkVehicleVin, createVehicle, uploadVehiclePhotos } from '../services/vehicles'
import type { Customer, Workshop } from '../types'

const route = useRoute()
const workshops = ref<Workshop[]>([]); const customers = ref<Customer[]>([])
const workshopId = ref<number | null>(route.query.workshop_id ? Number(route.query.workshop_id) : null); const customerId = ref<number | null>(route.query.customer_id ? Number(route.query.customer_id) : null)
const vin = ref(''); const make = ref(''); const model = ref(''); const year = ref(new Date().getFullYear()); const plate = ref(''); const files = ref<File[]>([]); const previews = ref<string[]>([]); const photoInputKey = ref(0); const saving = ref(false); const checking = ref(false); const vinVerified = ref(false); const duplicate = ref(false); const error = ref(''); const notice = ref('')
const activeWorkshopSelected = computed(() => !!workshopId.value && workshops.value.some(item => item.id === workshopId.value && item.is_active !== false))
const activeCustomerSelected = computed(() => !!customerId.value && customers.value.some(item => item.id === customerId.value && item.is_active))
const valid = computed(() => activeWorkshopSelected.value && activeCustomerSelected.value && /^[A-HJ-NPR-Z0-9]{17}$/.test(vin.value) && vinVerified.value && !duplicate.value && make.value.trim().length >= 2 && !!model.value.trim() && year.value >= 1886 && year.value <= 2100)
async function loadCustomers() { customers.value = workshopId.value ? await listCustomers({ workshop_id: workshopId.value, status_filter: 'activos' }) : []; if (customerId.value && !customers.value.some(x => x.id === customerId.value)) customerId.value = null }
async function verifyVin() { duplicate.value = false; vinVerified.value = false; if (!/^[A-HJ-NPR-Z0-9]{17}$/.test(vin.value)) return; checking.value = true; try { duplicate.value = (await checkVehicleVin(vin.value)).duplicate; vinVerified.value = !duplicate.value } catch { error.value = 'No fue posible comprobar el VIN.' } finally { checking.value = false } }
function chooseFiles(event: Event) { const chosen = Array.from((event.target as HTMLInputElement).files || []); for (const file of chosen) { if (!['image/jpeg','image/png','image/webp'].includes(file.type)) { error.value = 'Las fotos deben ser JPG, PNG o WebP.'; return }; if (file.size > 15 * 1024 * 1024) { error.value = `${file.name} supera el límite de 15 MB.`; return } }; files.value = [...files.value, ...chosen]; previews.value = files.value.map(x => URL.createObjectURL(x)); (event.target as HTMLInputElement).value = '' }
function removePhoto(index: number) { const [preview] = previews.value.splice(index, 1); if (preview) URL.revokeObjectURL(preview); files.value.splice(index, 1) }
function resetForm() { previews.value.forEach(url => URL.revokeObjectURL(url)); workshopId.value = null; customerId.value = null; customers.value = []; vin.value = ''; make.value = ''; model.value = ''; year.value = new Date().getFullYear(); plate.value = ''; files.value = []; previews.value = []; photoInputKey.value += 1; checking.value = false; duplicate.value = false; vinVerified.value = false; error.value = '' }
async function save() { if (!valid.value || !workshopId.value || !customerId.value || saving.value) return; saving.value = true; error.value = ''; try { const result = await createVehicle(workshopId.value, customerId.value, { vin: vin.value, make: make.value, model: model.value, year: year.value, plate: plate.value || null }); if (files.value.length) await uploadVehiclePhotos(result.id, files.value); resetForm(); notice.value = 'El vehículo se registró correctamente.' } catch (cause: any) { error.value = cause.response?.data?.detail || 'No fue posible registrar el vehículo.' } finally { saving.value = false } }
onMounted(async () => { try { workshops.value = await activeWorkshops(); await loadCustomers() } catch { error.value = 'No fue posible cargar talleres o clientes activos.' } })
watch(error, value => { if (value) setTimeout(() => { if (error.value === value) error.value = '' }, 5000) })
watch(notice, value => { if (value) setTimeout(() => { if (notice.value === value) notice.value = '' }, 5000) })
</script>
<template>
  <v-container class="page-shell vehicle-register-page">
    <header class="page-header"><p class="eyebrow">VEHÍCULOS</p><div class="header-row"><div class="header-icon"><v-icon icon="mdi-car-info" size="27"/></div><div><h1>Registrar vehículo</h1><p class="subtitle">Asocia un vehículo a un cliente activo dentro de su centro automotriz.</p></div></div></header>
    <v-alert v-if="notice" class="vehicle-register-success mb-5" variant="flat"><v-icon icon="mdi-check-circle" class="mr-2" />{{ notice }}</v-alert><v-alert v-if="error" type="error" variant="tonal" closable class="mb-5" @click:close="error=''">{{ error }}</v-alert><v-alert v-if="duplicate" type="warning" variant="tonal" class="mb-5">Este VIN ya está registrado. No se puede crear una segunda unidad.</v-alert>
    <div class="form-grid"><v-card class="module-card" elevation="0"><v-card-text><div class="card-title"><div class="card-icon"><v-icon icon="mdi-account-switch-outline"/></div><div><h2>Asociación</h2><p>Centro automotriz y cliente propietario.</p></div></div><v-divider class="my-5"/><v-select v-model="workshopId" label="Centro automotriz asociado *" :items="workshops" item-title="name" item-value="id" prepend-inner-icon="mdi-storefront-outline" variant="outlined" density="comfortable" @update:model-value="loadCustomers"/><v-select v-model="customerId" class="mt-4" label="Cliente asociado *" :items="customers" :item-title="(x:Customer)=>`${x.first_name} ${x.paternal_surname}`" item-value="id" prepend-inner-icon="mdi-account-outline" variant="outlined" density="comfortable" :disabled="!workshopId"/></v-card-text></v-card><v-card class="module-card" elevation="0"><v-card-text><div class="card-title"><div class="card-icon"><v-icon icon="mdi-car-info"/></div><div><h2>Datos del vehículo</h2><p>El VIN se verifica antes de crear la asociación.</p></div></div><v-divider class="my-5"/><v-row><v-col cols="12"><v-text-field :model-value="vin" label="Número de serie (VIN) *" maxlength="17" hint="17 caracteres alfanuméricos; sin I, O ni Q" persistent-hint prepend-inner-icon="mdi-barcode" variant="outlined" density="comfortable" :loading="checking" @blur="verifyVin" @update:model-value="vin=String($event).toUpperCase().replace(/[^A-Z0-9]/g,'');duplicate=false;vinVerified=false"/></v-col><v-col cols="12" md="6"><v-text-field v-model.trim="make" class="vehicle-data-field" label="Marca *" prepend-inner-icon="mdi-car-cog" variant="outlined" density="comfortable"/></v-col><v-col cols="12" md="6"><v-text-field v-model.trim="model" class="vehicle-data-field" label="Modelo *" prepend-inner-icon="mdi-car-side" variant="outlined" density="comfortable"/></v-col><v-col cols="12" md="6"><v-text-field v-model.number="year" class="vehicle-data-field" label="Año *" type="number" prepend-inner-icon="mdi-calendar-outline" variant="outlined" density="comfortable"/></v-col><v-col cols="12" md="6"><v-text-field v-model.trim="plate" class="vehicle-data-field" label="Placas (opcional)" prepend-inner-icon="mdi-card-text-outline" variant="outlined" density="comfortable"/></v-col></v-row></v-card-text></v-card></div>
    <v-card class="module-card mt-6" elevation="0"><v-card-text><div class="card-title"><div class="card-icon"><v-icon icon="mdi-camera-outline"/></div><div><h2>Fotografías del vehículo</h2><p>Una o varias fotos JPG, PNG o WebP. Máximo 15 MB por archivo.</p></div></div><v-divider class="my-5"/><v-file-input :key="photoInputKey" label="Seleccionar fotografías" multiple accept="image/jpeg,image/png,image/webp" prepend-icon="mdi-image-multiple-outline" variant="outlined" density="comfortable" show-size chips @change="chooseFiles"/><div v-if="previews.length" class="photo-grid"><div v-for="(preview,index) in previews" :key="preview" class="photo-item"><v-img :src="preview" cover height="130"/><v-btn icon="mdi-close" size="x-small" color="error" variant="flat" class="remove-photo" @click="removePhoto(index)"/></div></div></v-card-text></v-card>
    <footer class="action-footer"><p>Se validará asociación, VIN y fotografías antes de registrar.</p><v-btn class="vehicle-register-button" color="primary" size="large" prepend-icon="mdi-car-info" :disabled="!valid || saving || checking" :loading="saving" @click="save">Registrar vehículo</v-btn></footer>
  </v-container>
</template>
<style scoped>
.page-shell{max-width:1120px;padding:38px 32px 64px}.page-header{margin-bottom:28px}.header-row,.card-title{display:flex;gap:14px;align-items:flex-start}.header-icon,.card-icon{display:grid;place-items:center;flex:none;border-radius:12px;background:#edf3ff;color:#3867de}.header-icon{width:52px;height:52px}.card-icon{width:42px;height:42px}.eyebrow{margin:0 0 8px;color:#3364a2;font-weight:800;letter-spacing:1.3px;font-size:.72rem}.page-header h1{margin:0;color:#172b4d;font-size:clamp(1.8rem,2.6vw,2.3rem);line-height:1.15;font-weight:800}.subtitle,.card-title p{margin:5px 0 0;color:#66758b;font-size:.88rem}.form-grid{display:grid;grid-template-columns:.9fr 1.15fr;gap:24px;align-items:start}.module-card,.action-footer{border:1px solid #e4e9f2;border-radius:16px;background:#fff;box-shadow:0 12px 28px rgba(23,43,77,.05)}.module-card{padding:6px}.card-title h2{margin:0;color:#172b4d;font-size:1.05rem}.action-footer{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:18px 24px;margin-top:24px}.action-footer p{margin:0;color:#748197;font-size:.84rem}.action-footer .v-btn{text-transform:none;font-weight:700;border-radius:11px}.photo-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:14px}.photo-item{position:relative;overflow:hidden;border-radius:10px;border:1px solid #e4e9f2}.remove-photo{position:absolute;right:6px;top:6px}@media(max-width:900px){.form-grid{grid-template-columns:1fr}}@media(max-width:600px){.page-shell{padding:24px 16px 42px}.action-footer{align-items:stretch;flex-direction:column;text-align:center}}:global(.v-theme--dark) .module-card,:global(.v-theme--dark) .action-footer{background:#1e3559;border-color:#30496e}:global(.v-theme--dark) .page-header h1,:global(.v-theme--dark) .card-title h2{color:#f4f7ff}:global(.v-theme--dark) .subtitle,:global(.v-theme--dark) .card-title p,:global(.v-theme--dark) .action-footer p{color:#c3d6ea}
</style>
<style scoped>
.vehicle-register-page .card-icon{background:#f8e9ce;color:#2850e8}.vehicle-register-page .vehicle-data-field :deep(.v-field__prepend-inner .v-icon){color:#7b8798!important}.vehicle-register-success{border:1px solid rgba(35,126,24,.2)!important;background:#eaf7ea!important;color:#237e18!important;font-weight:700}.vehicle-register-success :deep(.v-icon){color:#237e18!important}.vehicle-register-button{background:#2850e8!important;color:#fff!important;transition:background-color .2s ease!important}.vehicle-register-button:hover:not(.v-btn--disabled),.vehicle-register-button:focus-visible:not(.v-btn--disabled){background:#253b60!important;color:#fff!important}.vehicle-register-button :deep(.v-icon){color:#fff!important}:global(.v-theme--dark) .vehicle-register-page .card-icon{background:#f8e9ce;color:#2850e8}:global(.v-theme--dark) .vehicle-register-success{background:rgba(35,126,24,.2)!important;border-color:rgba(104,190,94,.36)!important;color:#c9edc4!important}:global(.v-theme--dark) .vehicle-register-success :deep(.v-icon){color:#8fd68a!important}
</style>
